findings = []
for ident, treatment, thread, needle, issue, prevention, checks in rows:
    candidates = [m for m in threads[thread]['messages'] if needle.casefold() in m['text'].casefold()]
    # A few report findings were only in a final finding summary. Keep absence
    # explicit rather than manufacturing an exact quote or timestamp.
    evidence = [{'line': m['line'], 'timestamp': m['timestamp'], 'text': m['text']}
                for m in candidates]
    findings.append(dict(id=ident, treatment=treatment, thread=thread, issue=issue,
                         mechanism=prevention, checks=checks, evidence=evidence,
                         search=needle, evidence_status='matched' if evidence else 'needs-report-anchor'))

out = Path('research/execution-protocol-audit')
out.mkdir(parents=True, exist_ok=True)
(out / 'findings.json').write_text(json.dumps(findings, indent=2) + '\n')
print('FINDINGS',len(findings),'matched',sum(bool(f['evidence']) for f in findings))
print('UNMATCHED',[(f['id'],f['search']) for f in findings if not f['evidence']])
